def outlier_function(df, col_name):
    first_quartile = numpy.percentile(numpy.array(df[col_name].tolist()), 25)
    third_quartile = numpy.percentile(numpy.array(df[col_name].tolist()), 75)
    IQR = third_quartile - first_quartile
    upper_limit = third_quartile + 3 * IQR
    lower_limit = first_quartile - 3 * IQR
    outlier_count = 0
    for value in df[col_name].tolist():
        if (value < lower_limit) | (value > upper_limit):
            outlier_count += 1
    return (lower_limit, upper_limit, outlier_count)

for str in pandas.core.frame.DataFrame.columns:
    if outlier_function(pandas.core.frame.DataFrame, str)[2] > 0:
        print('There are {} outliers in {}'.format(outlier_function(pandas.core.frame.DataFrame, str)[2], str))

